
import argparse, subprocess, sys, datetime, base64
from pathlib import Path

EMAIL_B64 = """"""
WHICH_B64 = """aW1wb3J0IGVtYWlsLCBzeXMsIHNzbApwcmludCgnZW1haWwgbW9kdWxlIGZpbGU6JywgZ2V0YXR0cihlbWFpbCwgJ19fZmlsZV9fJywgJzxidWlsdC1pbj4nKSkKcHJpbnQoJ3B5dGhvbjonLCBzeXMudmVyc2lvbikKcHJpbnQoJ29wZW5zc2w6Jywgc3NsLk9QRU5TU0xfVkVSU0lPTik="""

def run(a, cwd=None, check=True):
    subprocess.run(a, cwd=cwd, check=check)

def find_root(seed: Path) -> Path:
    p = seed
    for _ in range(8):
        if (p/'.git').exists():
            return p
        p = p.parent
    return seed

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--repo-root', default='')
    a = ap.parse_args()

    here = Path(__file__).resolve()
    root = Path(a.repo_root) if a.repo_root else find_root(here)
    if not (root/'.git').exists():
        print('Repo root not found', file=sys.stderr); return 2

    # Write files from embedded payloads
    (root/'tools/py').mkdir(parents=True, exist_ok=True)
    (root/'tools/py/email_watcher.py').write_text(base64.b64decode(EMAIL_B64).decode('utf-8'), encoding='utf-8')
    (root/'tools/py/which_email_module.py').write_text(base64.b64decode(WHICH_B64).decode('utf-8'), encoding='utf-8')

    # Git ops
    step='PA-302'; branch=f'step/{step}-fix-files'
    run(['git','checkout','-B',branch], root)
    run(['git','add','-A'], root)
    ts = datetime.datetime.now().strftime('%Y%m%d_%H%M')
    run(['git','commit','-m', f'{step}: replace watcher with stable version; add which_email helper'], root, check=False)
    run(['git','push','-u','origin',branch], root, check=False)
    print(f'{step} done.')

if __name__ == '__main__':
    sys.exit(main())
